// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;

    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 time, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);
        time = bound(time, 0, block.timestamp - 1); // any time in the past
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(time);
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}
